from lib import *
S = SS('t16')
steps = [
    step("全量对账:订单库和支付库各 10 万个订单规模(订单库 100000 行,其中 PAID 89972;支付库 89792 行),按固定比例注入四类分歧——丢失 1%(899 个)、重复 0.5%(450 个)、金额不一致 0.5%(450 个)、孤儿约 0.27%(269 个)。两边各按订单号排序流式读出再归并比较,归并了 90241 个订单号,用时 0.36 s:四类分歧全部命中,误报 0、漏报 0。对账规则很朴素:订单是 PAID,支付库里必须有且只有一条金额相同的支付。", t=tl(S(1)), mark=lidx(S(1), '丢失(订单已付', '孤儿(有支付'), done=lidx(S(1), '归并比较了'), b=bars([['丢失:命中 / 注入', 899, '899 / 899'], ['重复:命中 / 注入', 450, '450 / 450'], ['金额不一致:命中 / 注入', 450, '450 / 450'], ['孤儿:命中 / 注入', 269, '269 / 269']], 900, done=[0, 1, 2, 3]), kv=KV([['全量对账', '0.36 s,10 万订单'], ['命中', '2068 个分歧全部发现'], ['误报 / 漏报', '0 / 0']], ['命中'])),
    step("增量对账(只比 updated_at 落在最近一个窗口里的行)会漏报:共 2068 个分歧,时间戳均匀散在 24 小时里。最近 1 小时只发现 97 个(召回率 5%),还有 2 个误报;最近 6 小时发现 520 个(25%);最近 24 小时发现 2068 个(100%)。当支付库的时钟比订单库慢 5 分钟(支付行盖的时间比真实时间早 5 分钟)时,最近 6 小时仍然只发现 518 个,却多出 311 个误报:订单在窗口里,它的支付时间戳落到了窗口外,被报成“丢失”。窗口外的分歧永远发现不了,窗口边缘还会误报,所以增量对账要有重叠窗口,并定期做全量。", t=tl(S(2)), mark=lidx(S(2), '最近 1 小时', '时钟慢 5 分钟'), done=lidx(S(2), '最近 24 小时'), b=bars([['最近 1 小时:发现', 97, '97 / 2068'], ['最近 6 小时:发现', 520, '520 / 2068'], ['最近 24 小时:发现', 2068, '2068 / 2068'], ['6 小时 + 时钟慢 5 分钟:误报', 311, '311']], 2068, cur=[0, 1], done=[2], mark=[3]), kv=KV([['窗口越小', '召回率越低(1 小时 5%)'], ['窗口之外', '永远发现不了'], ['时钟偏差', '边缘上出 311 个误报']], ['时钟偏差'])),
    step("业务还在写入时对账:订单提交之后 80 ms 支付才提交(正常的延迟),此时对账会把“正在途中”的订单报成丢失。写入线程在这段时间共产生 147 个订单,所有订单的支付最终都落地了(没有真实分歧),所以出现的“丢失”全是误报。宽限期 0 秒(所有订单都检查):每次检查平均看到 57 个新订单,误报 0.6 个,最多一次 1 个;宽限期 1 秒(只对提交超过 1 秒的订单下结论):平均 86 个新订单,误报 0;宽限期 3 秒:平均 102 个,误报 0。宽限期换来 0 误报,代价是真正的分歧要等宽限期之后才发现。", t=tl(S(3)), mark=lidx(S(3), '宽限期 0 秒'), done=lidx(S(3), '宽限期 1 秒', '宽限期 3 秒'), b=bars([['宽限期 0 秒:每次误报', 0.6, '0.6'], ['宽限期 1 秒:每次误报', 0, '0'], ['宽限期 3 秒:每次误报', 0, '0']], 1, mark=[0], done=[1, 2]), kv=KV([['无宽限期', '正在途中的订单被报成丢失'], ['宽限期 1 秒起', '0 误报'], ['代价', '分歧发现得更晚']], ['代价'])),
    step("修复:以订单库为准,写成幂等的修复动作——丢失补一条支付(用 where not exists 保证只补一次)、重复把多余的标成 REFUNDED、金额不一致按订单金额更正、孤儿标成 REFUNDED。第一次修复用时 0.15 s,各类动作数 899、450、450、269,正好等于发现的分歧数。修复之后重新对账(只看状态为 PAID 的支付),四类分歧都是 0;再基于重新对账的结果跑一遍修复,动作数全是 0——修复是幂等的,重复执行不会再动手。", t=tl(S(4)), mark=lidx(S(4), '第一次修复'), done=lidx(S(4), '修复之后重新对账', '再跑一遍修复'), b=bars([['第一次修复动作总数', 2068, '2068'], ['修复后重新对账的分歧', 0, '0'], ['再跑一遍修复的动作', 0, '0']], 2068, cur=[0], done=[1, 2]), kv=KV([['规则', '以订单库为准'], ['修复', '补、冲、改、退,全部幂等'], ['验证', '修完重新对账 0 分歧']], ['验证'])),
    step("全量对账的成本随规模的变化(两边分歧比例相同):2 万订单用时 0.08 s(252082 订单/秒),10 万订单 0.36 s(279396 订单/秒),30 万订单 1.04 s(288592 订单/秒),发现的分歧总数分别是 415、2070、6212 个。用时随订单数大致线性增长,吞吐稳定在每秒约 25 万到 29 万个订单。这里只比较了金额与笔数,没有比较其它字段;两个库在同一台机器上,没有网络开销。", t=tl(S(5)), mark=lidx(S(5), '300000'), done=lidx(S(5), '20000', '100000'), b=bars([['2 万订单用时 s', 0.08, '0.08'], ['10 万订单用时 s', 0.36, '0.36'], ['30 万订单用时 s', 1.04, '1.04']], 1.1, cur=[0, 1, 2]), kv=KV([['用时', '随订单数线性增长'], ['吞吐', '约 25 万 ~ 29 万订单/秒'], ['未覆盖', '更多字段、跨网络']], ['未覆盖'])),
]
A = mkartt('t16', 16, '分布式事务,最终一致,对账,修复,MySQL,真实验证,动画演示',
    '实测最终一致的对账与修复:10 万订单全量对账 0.36 s 发现全部 2068 个分歧(丢失、重复、金额不一致、孤儿)、0 误报;只比最近 1 小时只能发现 5%,支付库时钟慢 5 分钟会出 311 个误报;宽限期 1 秒消除途中订单的误报;幂等修复后重新对账 0 分歧,再修复 0 动作。',
    '最终一致意味着短暂的不一致是允许的,但不能永远不一致。靠什么发现?全量还是增量?业务还在写时怎么避免误报?发现之后怎么修?这篇用两个真实的 MySQL 和 10 万个订单,把对账与修复的这些环节逐个量出来。',
    [('0.36 s', '10 万订单、两个库的全量对账用时,发现全部 2068 个注入的分歧(误报 0、漏报 0)'), ('5%', '只对账最近 1 小时时的召回率(24 小时窗口才是 100%)'), ('311', '支付库时钟慢 5 分钟时,6 小时窗口里多出来的误报数')],
    [('全量对账', '<p>两边按订单号排序流式读出、归并比较:订单是 PAID 就必须有且只有一条金额相同的支付。四类分歧全部发现,误报漏报都是 0。</p>'),
     ('增量对账的局限', '<p>只比最近窗口的话,窗口外的分歧永远发现不了;窗口边缘和时钟偏差还会误报。需要重叠窗口并定期做全量。</p>'),
     ('在线写入的误报', '<p>订单已提交、支付还在路上的订单会被报成丢失。只对足够老的行下结论,用宽限期消除。</p>'),
     ('幂等的修复', '<p>补、冲、改、退都写成可重复执行,修复后重新对账验证,再修一次不会再动手。</p>'),
     ('成本', '<p>全量对账用时随订单数线性增长,这里每秒约 25 万到 29 万个订单。</p>')],
    steps,
    [ENV_T + '。本篇用两个独立的 MySQL 26.7.0 实例(订单库、支付库),10 万个订单(其中约 90% 是 PAID),分歧是按固定比例、固定随机种子注入的;对账用服务端游标流式读取(PyMySQL SSCursor),不涉及网络;第三节的写入线程在订单提交 80 ms 后才提交支付,是我设的延迟',
     '没有验证:真实业务里分歧的种类和比例(这里的比例是我设的);比较更多字段(状态、时间)时的开销;跨机房网络下对账的耗时;对账期间读到的是一致快照吗(这里没有做快照一致性读);修复动作造成的二次影响(例如退款会触发别的流程);“孤儿”的判定会混进已取消订单,本数据里没有这种情况'],
    '最终一致的对账')
